/**
 * Project quota, slug suggestion and the archive cascade.
 *
 * Owner C implements `@/server/services/project-service`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

function projectInput(
  orgId: OrgId,
  overrides: Partial<{ name: string; slug: string; key: string }> = {},
): CreateProjectInput {
  return {
    orgId,
    name: overrides.name ?? "Widget Works",
    slug: overrides.slug ?? "widget-works",
    key: overrides.key ?? "WID",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("services/project-service", () => {
  it("refuses creation once the plan's project quota is reached", async () => {
    // `createTenant` already inserts one project, so the free plan's ceiling
    // of two projects is one `createProject` call away.
    const tenant = await createTenant("projquota", "free");

    await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Second Project", slug: "second", key: "SEC" }),
    );

    await expect(
      projectService.createProject(
        tenant.actors.member,
        projectInput(tenant.org.id, { name: "Third Project", slug: "third", key: "THI" }),
      ),
    ).rejects.toThrow(/allows 2 projects/);
  });

  it("suggests a suffixed slug when the requested one is taken", async () => {
    // `createTenant` seeds a project already slugged "platform".
    const tenant = await createTenant("projslug", "growth");
    expect(tenant.project.slug).toBe("platform");

    await expect(
      projectService.suggestProjectSlug(tenant.org.id, "Platform"),
    ).resolves.toBe("platform-2");
  });

  it("scopes slug uniqueness to the organization", async () => {
    const tenantA = await createTenant("slugorga", "growth");
    const tenantB = await createTenant("slugorgb", "growth");

    await projectService.createProject(
      tenantB.actors.member,
      projectInput(tenantB.org.id, { name: "Rocket", slug: "rocket", key: "ROC" }),
    );

    // "rocket" is taken in org B but free in org A.
    await expect(
      projectService.suggestProjectSlug(tenantA.org.id, "Rocket"),
    ).resolves.toBe("rocket");
  });

  it("cascades the archive to the project's issues when asked", async () => {
    const tenant = await createTenant("archivecascade", "growth");

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live issue 1" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live issue 2" }),
    );

    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(2);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: true,
    });

    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(0);
    expect(
      await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).toBe(2);
  });

  it("emits project.archived with the number of issues archived", async () => {
    const tenant = await createTenant("archiveevent", "growth");

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "To be archived" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Also archived" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived too" }),
    );

    const received: unknown[] = [];
    const off = subscribe("project.archived", (payload) => {
      received.push(payload);
    });

    try {
      const archived = await projectService.archiveProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        archiveIssues: true,
      });

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({ projectId: archived.id, issuesArchived: 3 });
    } finally {
      off();
    }
  });

  it("restores an archived project and emits project.restored", async () => {
    const tenant = await createTenant("restoreproj", "growth");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const received: unknown[] = [];
    const off = subscribe("project.restored", (payload) => {
      received.push(payload);
    });

    try {
      const restored = await projectService.restoreProject(
        tenant.actors.admin,
        tenant.org.id,
        tenant.project.id,
      );

      expect(restored.archivedAt).toBeNull();

      const stored = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
      expect(stored?.archivedAt).toBeNull();

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({ projectId: tenant.project.id });
    } finally {
      off();
    }
  });
});
/**
 * Slug uniqueness and archive/restore round-trip.
 *
 * Owner C implements `@/server/repositories/project-repository`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as projectRepo from "@/server/repositories/project-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind-projects");
  acme = await createTenant("acme-projects");
});

afterAll(() => {
  cleanup();
});

describe("repositories/project-repository", () => {
  it("allows the same slug in two different organizations", async () => {
    // createTenant already gave each org a project slugged "platform".
    expect(north.project.slug).toBe("platform");
    expect(acme.project.slug).toBe("platform");
    expect(north.project.id).not.toBe(acme.project.id);
  });

  it("refuses a duplicate slug inside one organization", async () => {
    const second = await projectRepo.insertProject({
      orgId: north.org.id,
      name: "Second platform",
      slug: "platform",
      key: "SECD",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    expect(second.slug).not.toBe("platform");
    expect(second.id).not.toBe(north.project.id);

    const original = await projectRepo.findProjectBySlug(north.org.id, "platform");
    expect(original?.id).toBe(north.project.id);
  });

  it("scopes findBySlug to the organization", async () => {
    const found = await projectRepo.findProjectBySlug(acme.org.id, "platform");
    expect(found?.id).toBe(acme.project.id);
    expect(found?.id).not.toBe(north.project.id);
  });

  it("archives by stamping archived_at, keeping the row", async () => {
    const created = await projectRepo.insertProject({
      orgId: north.org.id,
      name: "To archive",
      slug: "to-archive",
      key: "ARCH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const archived = await projectRepo.archiveProject(north.org.id, created.id);
    expect(archived.archivedAt).not.toBeNull();

    const stillThere = await projectRepo.findProjectById(north.org.id, created.id);
    expect(stillThere).not.toBeNull();
    expect(stillThere?.archivedAt).not.toBeNull();
  });

  it("restores an archived project", async () => {
    const created = await projectRepo.insertProject({
      orgId: north.org.id,
      name: "To restore",
      slug: "to-restore",
      key: "REST",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await projectRepo.archiveProject(north.org.id, created.id);
    const restored = await projectRepo.restoreProject(north.org.id, created.id);

    expect(restored.archivedAt).toBeNull();

    const page = await projectRepo.listProjects({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });
    expect(page.items.map((row) => row.id)).toContain(created.id);
  });

  it("excludes archived projects from the default listing", async () => {
    const created = await projectRepo.insertProject({
      orgId: north.org.id,
      name: "Stays archived",
      slug: "stays-archived",
      key: "STAY",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectRepo.archiveProject(north.org.id, created.id);

    const defaultPage = await projectRepo.listProjects({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });
    expect(defaultPage.items.map((row) => row.id)).not.toContain(created.id);

    const withArchived = await projectRepo.listProjects({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
      includeArchived: true,
    });
    expect(withArchived.items.map((row) => row.id)).toContain(created.id);
  });
});
"use server";

/**
 * Restores an archived project.
 *
 * Owner D. There is no `restoreProjectSchema` in `src/schemas` because the
 * payload is nothing but the two ids, so the shape is composed here from the
 * shared branded-id primitives rather than added to the frozen schema layer.
 *
 * Must call (do not reimplement): can, restorePatch, getActor, toActionResult
 */

import { ActionNotFoundError, ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { restorePatch } from "@/lib/soft-delete";
import { orgIdSchema, projectIdSchema } from "@/schemas/common";
import { listProjects, restoreProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";
import { z } from "zod";

const restoreProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
});

type RestoreProjectInput = z.infer<typeof restoreProjectSchema>;

const run = withAction<typeof restoreProjectSchema, Project>(
  restoreProjectSchema,
  async (raw, actor) => {
    const input = raw as RestoreProjectInput;

    const page = await listProjects(actor, {
      orgId: input.orgId,
      limit: 100,
      includeArchived: true,
    });
    const current = page.items.find((row) => row.project.id === input.projectId);
    if (current === undefined) {
      throw new ActionNotFoundError(`project ${input.projectId}`);
    }

    const allowed = can(actor, "project:archive", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: current.project.visibility,
      leadId: current.project.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:archive");
    }

    const project = await restoreProject(actor, input.orgId, input.projectId);

    // `restorePatch()` is the single definition of what "restored" looks like;
    // comparing against it catches a service that forgot to clear the column.
    const expected = restorePatch();
    if (project.archivedAt !== expected.archivedAt) {
      throw new ActionNotFoundError(`live project ${input.projectId}`);
    }

    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function restoreProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
