export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Derives a project key that collides with nothing in `taken`, by appending
 * `2`, `3`, … and trimming the base so the key never exceeds four characters
 * (`WEBV` → `WEB2`). Mirrors `uniqueSlug`; the repository passes every key in
 * the organization in, archived projects included, since their issue numbers
 * still carry the key.
 */
export function uniqueKey(input: string, taken: Iterable<string>): string {
  const used = new Set(taken);
  if (!used.has(input)) return input;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    const candidate = `${input.slice(0, PROJECT_KEY_MAX_LENGTH - tail.length)}${tail}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new Error(`No free project key left for ${input}`);
}

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */

