/**
 * Restore does not un-archive the issues: they are restored individually.
 * Only an archived project can come back, and only while the plan has a free
 * slot for it; a refusal restores nothing and announces nothing.
 */
export async function restoreProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));

  if (isLive(project)) {
    throw new Error(`Project ${project.key} is not archived; nothing to restore`);
  }

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const used = await projectRepo.countProjects(orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to restore another`,
    );
  }

  const restored = await projectRepo.restoreProject(orgId, projectId);

